  -- Block #6: replaces the section whose old copy contains 'Boostez votre'.
  UPDATE public.blocks
     SET content = $nb${"padding":{"top":"xl","bottom":"xl"},"background":{"type":"gradient","gradient":{"type":"linear","stops":[{"color":"#1e1b4b","position":0},{"color":"#0f172a","position":100}],"direction":"135deg"}},"column_gap":"xl","column_blocks":[[{"content":{"html_content":"<p class='text-xs uppercase tracking-[0.3em] text-violet-400 font-semibold mb-4'>Maintenant disponible — Cortex AI</p><h2 class='text-4xl md:text-5xl font-bold text-white mb-6 leading-tight'>Le CMS est gratuit.<br/>Cortex AI est la mise à niveau.</h2><p class='text-lg text-slate-300 max-w-2xl leading-relaxed mb-4'>NextBlock ne coûte rien et ne coûtera jamais rien. Cortex AI est la seule licence que nous vendons. Elle ajoute l'IA dans l'éditeur et un serveur MCP à l'extérieur, pour que Claude Code, Cursor, ChatGPT et Gemini puissent bâtir votre site.</p><p class='text-base text-slate-400 max-w-2xl leading-relaxed'>Essayez-la gratuitement pendant 30 jours, sans carte de crédit. Vous apportez l'abonnement IA que vous payez déjà. La licence achète la connexion, jamais les jetons, et rien n'est mis en ligne tant qu'un éditeur ne l'a pas publié.</p>"},"block_type":"text"},{"content":{"url":"https://nextblock.dev/product/nextblock-cortex-ai-cortex-ai-license-fr","size":"lg","text":"Commencer l'essai gratuit de 30 jours →","variant":"default","position":"left"},"block_type":"button"},{"content":{"url":"/article/guide-connexion-mcp-cortex-ai","size":"lg","text":"Lire le guide de configuration MCP","variant":"outline","position":"left"},"block_type":"button"}],[{"content":{"html_content":"<div class='grid grid-cols-1 gap-4 sm:grid-cols-3 lg:grid-cols-1'><div class='rounded-2xl border border-violet-500/30 bg-white/5 p-6 text-center'><p class='text-3xl font-extrabold text-white'>$0</p><p class='text-xs uppercase tracking-wider text-violet-200 mt-1'>Le CMS, pour toujours</p></div><div class='rounded-2xl border border-violet-500/30 bg-white/5 p-6 text-center'><p class='text-3xl font-extrabold text-white'>30</p><p class='text-xs uppercase tracking-wider text-violet-200 mt-1'>jours de Cortex AI gratuits, sans carte</p></div><div class='rounded-2xl border border-violet-500/30 bg-white/5 p-6 text-center'><p class='text-3xl font-extrabold text-white'>0 %</p><p class='text-xs uppercase tracking-wider text-violet-200 mt-1'>de majoration sur les jetons</p></div></div>"},"block_type":"text"}]],"container_type":"container","responsive_columns":{"mobile":1,"tablet":1,"desktop":2},"vertical_alignment":"center"}$nb$::jsonb,
         updated_at = now()
   WHERE page_id = v_accueil
     AND "order" = 6
     AND block_type = 'section'
     AND content::text LIKE '%Boostez votre%';

  -- Page metadata: mirror the English title/description.
  UPDATE public.pages
     SET meta_title = 'NextBlock CMS',
